local function BUILD_POST_SELECTION_TRIGGER()
    hevent.reaction(
        CONST_EVENT.pickHero,
        "pick hero",
        function(evtData)
            hcamera.changeDistance(evtData.triggerPlayer, 1000)
            hattribute.set(evtData.triggerUnit, 0, _attr({ str_white = "=1", agi_white = "=1", int_white = "=1" }))
            hplayer.setPlayerTechResearched(evtData.triggerPlayer, c2i("R000"), 1)
            init_zhuangbei(evtData.triggerUnit)
            skill_init(evtData.triggerPlayer)
            -- 根据存档初始化英雄
            hplayer.init_from_cundang(evtData.triggerPlayer)
            check_shangcheng_zuobi(evtData.triggerPlayer)
            hquestcustom.setUpQuestTrigger(evtData.triggerPlayer)
            hjapi.DzSetUnitProperName(evtData.triggerUnit, hplayer.getName(evtData.triggerPlayer))

            if hhero.getExp(evtData.triggerUnit) == 0 then
                hquestcustom.enqueue_dialog(evtData.triggerPlayer, "？？？", "欢迎来到冒险者的世界。最近的村子不是很太平，村长似乎有事情找你。")
            end
            if hplayer.loc() == evtData.triggerPlayer then
                init_mainscene()
            end
            if hunit.getLevel(evtData.triggerUnit) <= 30 then
                hbuff.update(
                    -1,
                    evtData.triggerUnit,
                    "新手福利",
                    true,
                    function()
                        hattribute.set(evtData.triggerUnit, 0, { life_back = "+10" })
                    end,
                    function()
                        hattribute.set(evtData.triggerUnit, 0, { life_back = "-10" })
                    end,
                    "ReplaceableTextures\\xitong\\Achievement_Guild_DoctorIsIn.blp",
                    "新手福利：增加生命恢复速度10点/秒。开局生效，英雄等级超过30后失效。",
                    1,
                    nil,
                    nil,
                    nil,
                    nil,
                    HBUFF_UPDATE_MODE.CREATE_ONLY,
                    false
                )
            end
            init_period_job_for_player(evtData.triggerPlayer)
        end
    )
end

local function LOAD_CUNDANG()
    for _, v in ipairs(hplayer.players) do
        if hplayer.isUser(v) and hplayer.isPlaying(v) then
            hplayer.dzCunDang[v] = DZCunDang(v)
            hplayer.dzCunDang[v].loadCunDang()
        end
    end
end

INDEX_TO_HERONAME = {
    ["1"] = "火法",
    ["2"] = "狂暴战",
    ["3"] = "惩戒骑",
    ["4"] = "射击猎",
    ["5"] = "毁灭术",
    ["6"] = "星辰法师",
    ["7"] = "战斗贼",
    ["8"] = "武器战",
    ["9"] = "痛苦术",
    ["A"] = "恶魔猎手"
}

HERONAME_TO_INDEX = {}
for k, v in pairs(INDEX_TO_HERONAME) do
    HERONAME_TO_INDEX[v] = k
end

local setup_selection_dialog
setup_selection_dialog = function(whichPlayer)
    local heroCundang = hplayer.dzCunDang[whichPlayer].loadKeyFromCunDang("cundangherostr", false, false)
    local cundangcount = 3
    if hshangcheng.hasItem(whichPlayer, "第四存档位") then
        cundangcount = cundangcount + 1
    end
    if hshangcheng.hasItem(whichPlayer, "第五存档位") then
        cundangcount = cundangcount + 1
    end
    local availableButton = {}
    for i = 1, cundangcount, 1 do
        local index = string.sub(heroCundang, i, i) or "0"
        if INDEX_TO_HERONAME[index] then
            local laodedExp = hplayer.dzCunDang[whichPlayer].loadKeyFromCunDang("juese" .. i .. "jingyan", false, true)
            local experience = math.floor(tonumber(laodedExp) or 0)
            local level = hhero.getLevelGivenExp(experience, 70)
            table.insert(
                availableButton,
                {
                    value = i,
                    label = hcolor.white("存档" .. i .. "：") ..
                        hcolor.green(tostring(level)) .. hcolor.white("级" .. INDEX_TO_HERONAME[index])
                }
            )
        else
            table.insert(
                availableButton,
                {
                    value = i,
                    label = hcolor.white("空的存档")
                }
            )
        end
    end
    hdialog.create(
        whichPlayer,
        {
            title = "请选择存档位：",
            buttons = availableButton
        },
        function(cundangweiBtnValue)
            hplayer.dzCunDang[whichPlayer].setcundangwei(cundangweiBtnValue)
            local index = string.sub(heroCundang, cundangweiBtnValue, cundangweiBtnValue) or "0"
            if INDEX_TO_HERONAME[index] == nil then
                hcache.set(whichPlayer, "CAN_SELECT_HERO", true)
                hquestcustom.enqueue_dialog(whichPlayer, "？？？", "尊敬的冒险者，请双击选择英雄开始冒险。")
            else
                SELECT_HERO(whichPlayer, INDEX_TO_HERONAME[index])
            end
        end
    )
end

local function HERO_SELECTION()
    hhero.bornX = -31798
    hhero.bornY = -31124
    hcamera.setCameraRegion(hyewai["英雄选择区域"].rect)
    hplayer.forEach(
        function(enumPlayer, idx)
            if
                hplayer.isUser(enumPlayer) == false or hplayer.isPlaying(enumPlayer) == false or
                hplayer.isComputer(enumPlayer) == true
            then
                return
            end
            htime.setTimeout(
                60,
                function(curTimer)
                    if hplayer.getMainHero(enumPlayer) == nil then
                        hplayer.defeat(enumPlayer, "60秒内没有选择英雄，游戏失败")
                    end
                end
            )
            htime.setTimeout(
                1,
                function(curTimer)
                    setup_selection_dialog(enumPlayer)
                end
            )
        end
    )
end

function SELECT_HERO(whichPlayer, heroname)
    hplayer.dzCunDang[whichPlayer].saveCundang(
        "cundangherostr",
        false,
        hplayer.dzCunDang[whichPlayer]._cundangwei,
        hplayer.dzCunDang[whichPlayer]._cundangwei,
        tostring(HERONAME_TO_INDEX[heroname])
    )
    local startX = -30589
    local startY = -29131
    local pIndex = hplayer.index(whichPlayer)
    local newHero =
        hunit.create(
            {
                whichPlayer = whichPlayer,
                id = hslk.n2i(heroname),
                x = startX,
                y = startY,
                attr = {
                    reborn = DEFAULT_HERO_REBORN,
                    rebornX = startX,
                    rebornY = startY
                }
            }
        )
    table.insert(hhero.player_heroes[pIndex], newHero)
    echo("您选择了 " .. "|cffffff80" .. heroname .. "|r,已挑选完毕", whichPlayer)
    -- 触发英雄被选择事件(全局)
    hevent.trigger(
        "global",
        CONST_EVENT.pickHero,
        {
            triggerPlayer = whichPlayer,
            triggerUnit = newHero
        }
    )
end

